package org.example.api.profile;
import com.fasterxml.jackson.databind.*;import org.example.config.ConfigManager;import java.io.IOException;import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class ProfileApiClient {private final HttpClient http = org.example.api.ApiRuntime.HTTP;private final ObjectMapper json = org.example.api.ApiRuntime.JSON;private final String base;public ProfileApiClient(){String b=ConfigManager.getDataApiBaseUrl();while(b.endsWith("/"))b=b.substring(0,b.length()-1);base=b;}public ProfileDto current(){return request("GET",null);}public ProfileDto update(ProfileUpdate u){return request("PUT",u);}private ProfileDto request(String method,Object body){try{HttpRequest.Builder b=HttpRequest.newBuilder(URI.create(base+"/api/profile")).timeout(Duration.ofSeconds(20)).header("Accept","application/json");org.example.api.ApiSession.authorize(b);if(body==null)b.method(method,HttpRequest.BodyPublishers.noBody());else b.header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));var r=http.send(b.build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("Profile API error ("+r.statusCode()+"): "+r.body());return json.readValue(r.body(),ProfileDto.class);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}catch(IOException e){throw new IllegalStateException("Cannot reach profile API at "+base,e);}}public record ProfileDto(int id,String username,String fullName,String email,String role,String department,String branch,String accessLevel,boolean active,boolean locked,boolean mfaEnabled,String lastLogin){}public record ProfileUpdate(String fullName,String email,String department,String branch){}
}
